    int count = 0;
    int year = Y + 1;
    while (count < N) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            count++;
        }
        if (count < N) {
            year++;
        }
    }
    return year;
}

