public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    // Iterate over all possible substrings of the first string
    String firstString = strings.get(0);
    for (int i = 0; i < firstString.length(); i++) {
        for (int j = i + 1; j <= firstString.length(); j++) {
            String substring = firstString.substring(i, j);
            String reversedSubstring = new StringBuilder(substring).reverse().toString();

            // Check if this substring or its reverse is present in all strings
            boolean isCommon = true;
            for (String s : strings) {
                if (!s.contains(substring) && !s.contains(reversedSubstring)) {
                    isCommon = false;
                    break;
                }
            }

            // Update maxLength if this substring is common and longer than the current maxLength
            if (isCommon && substring.length() > maxLength) {
                maxLength = substring.length();
            }
        }
    }

    return maxLength;
}

