public static int maxRegions(int N) {
    if (N == 0) return 1; // Base case: No triangles, one region (the whole plane)
    if (N == 1) return 2; // One triangle, two regions

    int regions = 2; // Start with the base case of one triangle
    for (int i = 1; i <= N; i++) {
        regions += i * 3; // Each new triangle can intersect with all previous lines
    }
    return regions;
}

