public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a 2D array to represent the n-teresting space
    boolean[][] maze = new boolean[n][n];

    // Mark the paths in the maze
    for (int[] path : paths) {
        maze[path[0]][path[1]] = true;
        maze[path[1]][path[0]] = true; // assuming paths are bidirectional
    }

    // Use a queue for BFS
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Use a 2D array to keep track of visited n-tersections
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;

    // Perform BFS
    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        // If the current n-tersection is the end, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Explore all the adjacent n-tersections
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (int[] direction : directions) {
            int newX = current[0] + direction[0];
            int newY = current[1] + direction[1];

            // Check if the adjacent n-tersection is valid, passable, and not visited
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && maze[newX][newY] && !visited[newX][newY]) {
                queue.add(new int[]{newX, newY});
                visited[newX][newY] = true;
            }
        }
    }

    // If the end n-tersection is not reachable, return "cannot be travelled"
    return "cannot be travelled";
}

