public static String appx(String word1, String word2) {
    int commonCount = 0;
    String longer;
    String shorter;

    if (word1.length() >= word2.length()) {
        longer = word1.toLowerCase();
        shorter = word2.toLowerCase();
    } else {
        longer = word2.toLowerCase();
        shorter = word1.toLowerCase();
    }

    boolean[] used = new boolean[shorter.length()];

    for (int i = 0; i < longer.length(); i++) {
        char c = longer.charAt(i);
        for (int j = 0; j < shorter.length(); j++) {
            if (c == shorter.charAt(j) && !used[j]) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    int sumLengths = word1.length() + word2.length();
    int gcd = gcd(commonCount, sumLengths);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (sumLengths / gcd);
}

