    String[] daysOfWeek = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};

    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]) - 1; // Convert to 0-based index
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    // Using Zeller's Congruence algorithm to calculate the day of the week
    int q = day;
    int m = month + 1;
    int K = year % 100;
    int J = year / 100;

    int h = (q + 13 * (m + 1) / 5 + K + K / 4 + J / 4 + 5 * J) % 7;
    int dayOfWeek = (h + 5) % 7; // Convert Zeller's output to 0=Saturday, 1=Sunday, ..., 6=Friday

    return months[month] + " " + day + ", " + year + " is a " + daysOfWeek[dayOfWeek];
}

