public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (k >= num) {
                    dp[i][j][k] = dp[i - 1][j][k] || dp[i - 1][j - 1][k - num];
                } else {
                    dp[i][j][k] = dp[i - 1][j][k];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (dp[n][i][sum * i / n]) {
                return true;
            }
        }
    }

    return false;
}

