public boolean hasAllCodes(String s, int k) {
    int total = 1 << k; // 2^k
    boolean[] seen = new boolean[total];
    int value = 0;
    int mask = total - 1; // 2^k - 1

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & mask | (s.charAt(i) - '0');
        if (i >= k - 1 && !seen[value]) {
            seen[value] = true;
            total--;
            if (total == 0) {
                return true;
            }
        }
    }
    return false;
}

