public int minInsertions(String s) {
    int left = 0; // Number of unmatched '('
    int right = 0; // Number of needed ')'

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                // Need to insert a ')' to balance the current '('
                left++;
                right--;
            }
            right += 2; // Each '(' needs two ')'
        } else {
            right--;
            if (right == -1) {
                // More ')' than '('
                left++;
                right = 1; // We need one '(' to balance this ')'
            }
        }
    }

    return left + right;
}

