public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) continue;
        if (num >= low) result.add(num);

        if (num == 0) continue;

        int lastDigit = num % 10;
        int nextNum1 = num * 10 + lastDigit - 1;
        int nextNum2 = num * 10 + lastDigit + 1;

        if (lastDigit > 0 && nextNum1 <= high) {
            queue.offer(nextNum1);
        }
        if (lastDigit < 9 && nextNum2 <= high) {
            queue.offer(nextNum2);
        }
    }

    Collections.sort(result);
    return result;
}

