public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;

    // Fill left array where left[i] is the index of the first bar on the left
    // that is smaller than heights[i]
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j];
        }
        left[i] = j;
    }

    // Fill right array where right[i] is the index of the first bar on the right
    // that is smaller than heights[i]
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    // Calculate the max area by (right[i] - left[i] - 1) * heights[i]
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i] - 1) * heights[i]);
    }

