public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];

    int rows = mat.length, cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) {
            // Move up
            if (c == cols - 1) r++; // Reached last column, move down
            else if (r == 0) c++; // Reached first row, move right
            else { r--; c++; } // Move up diagonally
        } else {
            // Move down
            if (r == rows - 1) c++; // Reached last row, move right
            else if (c == 0) r++; // Reached first column, move down
            else { r++; c--; } // Move down diagonally
        }
    }
    return result;
}

