public static int minPerfectSquareSum(int n) {
    // Create an array to store the minimum number of perfect squares
    // for each number up to n.
    int[] dp = new int[n + 1];

    // Base case: zero can be represented by zero numbers.
    dp[0] = 0;

    // For each number i from 1 to n, calculate the minimum number of perfect squares.
    for (int i = 1; i <= n; i++) {
        // Initialize the minimum value to a large number.
        dp[i] = Integer.MAX_VALUE;

        // Check each perfect square less than or equal to i.
        for (int j = 1; j * j <= i; j++) {
            // Update the minimum value for dp[i].
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // The answer for n is stored in dp[n].
    return dp[n];
}

